-- Mensaje 108 · Una respuesta que contesta de pasada pero rechaza seguir sí es un «no» (Emilio: G29). Cerebro → reglas.
-- Protegido: si el Cerebro vigente no tiene el texto esperado, aborta sin tocar nada; el chequeo final aborta si algo no quedó.
DO $c$ DECLARE v int; BEGIN
  IF EXISTS (SELECT 1 FROM public.doctrina WHERE is_active AND strpos(body, $v$Una respuesta, aunque sea vaga o corta, no es un «no»: no rechazó nada, y lo que toca es seguir. Pero si en la misma respuesta contesta algo de pasada y rechaza seguir, sí es un «no»: cuenta lo que la respuesta hace con lo que el vendedor intentaba, no cómo empieza.$v$) > 0) THEN RAISE NOTICE 'El Cerebro ya tiene el cambio del 108.'; RETURN; END IF;
  SELECT max(version) INTO v FROM public.doctrina WHERE is_active;
  IF (SELECT count(*) FROM public.doctrina WHERE version = v AND strpos(body, $v$Una respuesta, aunque sea vaga o corta, no es un «no»: no rechazó nada, y lo que toca es seguir.$v$) > 0) <> 1 THEN RAISE EXCEPTION 'el Cerebro vigente no tiene el texto esperado'; END IF;
  INSERT INTO public.doctrina (version, section_key, order_index, title, body, is_active, created_by)
  SELECT v + 1, section_key, order_index, title, replace(body, $v$Una respuesta, aunque sea vaga o corta, no es un «no»: no rechazó nada, y lo que toca es seguir.$v$, $v$Una respuesta, aunque sea vaga o corta, no es un «no»: no rechazó nada, y lo que toca es seguir. Pero si en la misma respuesta contesta algo de pasada y rechaza seguir, sí es un «no»: cuenta lo que la respuesta hace con lo que el vendedor intentaba, no cómo empieza.$v$), true, created_by FROM public.doctrina WHERE version = v;
  UPDATE public.doctrina SET is_active = false WHERE is_active AND version = v;
END $c$;
UPDATE public.reglas SET resumen = $v$En cualquier momento de la visita, menos en el cierre, dos «no» seguidos son la señal de que hoy no es el día: se deja para otra visita (en la puerta, quedar de regresar con una alternativa concreta; al buscar el hueco, dejar de buscar). En el cierre son tres: la Regla de los No. LA PRUEBA DE UN «NO»: ¿la respuesta del cliente rechaza lo que el vendedor estaba intentando en ese momento —seguir la plática, explorar ese tema o avanzar a la decisión—, aunque traiga excusa? Entonces es un «no». Si contesta, aunque sea vago o corto, no es un «no». Si contesta algo de pasada pero en la misma respuesta rechaza seguir, sí es un «no»: cuenta lo que la respuesta hace, no cómo empieza. Si pone una duda, una condición o una objeción, tampoco: es una objeción. Seguidos: entre uno y otro la conversación no avanzó.$v$, updated_at = now() WHERE id = 'flow.dos_no_seguidos' AND resumen = $v$En cualquier momento de la visita, menos en el cierre, dos «no» seguidos son la señal de que hoy no es el día: se deja para otra visita (en la puerta, quedar de regresar con una alternativa concreta; al buscar el hueco, dejar de buscar). En el cierre son tres: la Regla de los No. LA PRUEBA DE UN «NO»: ¿la respuesta del cliente rechaza lo que el vendedor estaba intentando en ese momento —seguir la plática, explorar ese tema o avanzar a la decisión—, aunque traiga excusa? Entonces es un «no». Si contesta, aunque sea vago o corto, no es un «no». Si pone una duda, una condición o una objeción, tampoco: es una objeción. Seguidos: entre uno y otro la conversación no avanzó.$v$;
UPDATE public.reglas SET resumen = $v$Seguir insistiendo después de dos no seguidos en la puerta: ya no es seguridad, es terquedad. LA PRUEBA: ¿el cliente dio dos «no» seguidos en la puerta y, después del segundo, el vendedor sigue con su tema (otra pregunta, una explicación, un «nomás un minutito») en vez de quedar de regresar o despedirse? Solo cuenta lo que dice después del segundo no. LA PRUEBA DE UN «NO»: ¿la respuesta del cliente rechaza lo que el vendedor estaba intentando en ese momento —seguir la plática, explorar ese tema o avanzar a la decisión—, aunque traiga excusa? Entonces es un «no». Si contesta, aunque sea vago o corto, no es un «no». Si contesta algo de pasada pero en la misma respuesta rechaza seguir, sí es un «no»: cuenta lo que la respuesta hace, no cómo empieza. Si pone una duda, una condición o una objeción, tampoco: es una objeción. Seguidos: entre uno y otro la conversación no avanzó.$v$, updated_at = now() WHERE id = 'blocks.insistir_tras_dos_no' AND resumen = $v$Seguir insistiendo después de dos no seguidos en la puerta: ya no es seguridad, es terquedad. LA PRUEBA: ¿el cliente dio dos «no» seguidos en la puerta y, después del segundo, el vendedor sigue con su tema (otra pregunta, una explicación, un «nomás un minutito») en vez de quedar de regresar o despedirse? Solo cuenta lo que dice después del segundo no. LA PRUEBA DE UN «NO»: ¿la respuesta del cliente rechaza lo que el vendedor estaba intentando en ese momento —seguir la plática, explorar ese tema o avanzar a la decisión—, aunque traiga excusa? Entonces es un «no». Si contesta, aunque sea vago o corto, no es un «no». Si pone una duda, una condición o una objeción, tampoco: es una objeción. Seguidos: entre uno y otro la conversación no avanzó.$v$;
DO $chk$ DECLARE v int; n int; BEGIN
  SELECT max(version) INTO v FROM public.doctrina WHERE is_active;
  IF (SELECT count(*) FROM public.doctrina WHERE is_active) <> 7 THEN RAISE EXCEPTION 'el Cerebro no tiene 7 secciones activas'; END IF;
  IF (SELECT count(DISTINCT version) FROM public.doctrina WHERE is_active) <> 1 THEN RAISE EXCEPTION 'hay más de una versión activa del Cerebro'; END IF;
  IF (SELECT count(*) FROM public.doctrina WHERE is_active AND strpos(body, $v$Una respuesta, aunque sea vaga o corta, no es un «no»: no rechazó nada, y lo que toca es seguir. Pero si en la misma respuesta contesta algo de pasada y rechaza seguir, sí es un «no»: cuenta lo que la respuesta hace con lo que el vendedor intentaba, no cómo empieza.$v$) > 0) <> 1 THEN RAISE EXCEPTION 'el Cerebro no recibió el cambio'; END IF;
  SELECT count(*) INTO n FROM public.reglas r WHERE EXISTS (SELECT 1 FROM public.doctrina d WHERE d.version = v - 1 AND strpos(d.body, r.cita_cerebro) > 0) AND NOT EXISTS (SELECT 1 FROM public.doctrina d WHERE d.version = v AND strpos(d.body, r.cita_cerebro) > 0);
  IF n > 0 THEN RAISE EXCEPTION '% citas de reglas ya no están en el Cerebro', n; END IF;
  IF (SELECT resumen FROM public.reglas WHERE id = 'flow.dos_no_seguidos') IS DISTINCT FROM $v$En cualquier momento de la visita, menos en el cierre, dos «no» seguidos son la señal de que hoy no es el día: se deja para otra visita (en la puerta, quedar de regresar con una alternativa concreta; al buscar el hueco, dejar de buscar). En el cierre son tres: la Regla de los No. LA PRUEBA DE UN «NO»: ¿la respuesta del cliente rechaza lo que el vendedor estaba intentando en ese momento —seguir la plática, explorar ese tema o avanzar a la decisión—, aunque traiga excusa? Entonces es un «no». Si contesta, aunque sea vago o corto, no es un «no». Si contesta algo de pasada pero en la misma respuesta rechaza seguir, sí es un «no»: cuenta lo que la respuesta hace, no cómo empieza. Si pone una duda, una condición o una objeción, tampoco: es una objeción. Seguidos: entre uno y otro la conversación no avanzó.$v$ THEN RAISE EXCEPTION 'la regla flow.dos_no_seguidos no quedó'; END IF;
  IF (SELECT resumen FROM public.reglas WHERE id = 'blocks.insistir_tras_dos_no') IS DISTINCT FROM $v$Seguir insistiendo después de dos no seguidos en la puerta: ya no es seguridad, es terquedad. LA PRUEBA: ¿el cliente dio dos «no» seguidos en la puerta y, después del segundo, el vendedor sigue con su tema (otra pregunta, una explicación, un «nomás un minutito») en vez de quedar de regresar o despedirse? Solo cuenta lo que dice después del segundo no. LA PRUEBA DE UN «NO»: ¿la respuesta del cliente rechaza lo que el vendedor estaba intentando en ese momento —seguir la plática, explorar ese tema o avanzar a la decisión—, aunque traiga excusa? Entonces es un «no». Si contesta, aunque sea vago o corto, no es un «no». Si contesta algo de pasada pero en la misma respuesta rechaza seguir, sí es un «no»: cuenta lo que la respuesta hace, no cómo empieza. Si pone una duda, una condición o una objeción, tampoco: es una objeción. Seguidos: entre uno y otro la conversación no avanzó.$v$ THEN RAISE EXCEPTION 'la regla blocks.insistir_tras_dos_no no quedó'; END IF;
END $chk$;
